package studio.jiayu.neoagent;
import android.app.Activity;import org.json.*;import java.io.*;
/** Read-only local inventory and existing-consent checks; does not select new apps. */
final class AppInventoryContracts {
 static void run(Activity a){JSONObject out=new JSONObject();try{AppAccess access=new AppAccess(a);JSONObject state=access.state();JSONArray apps=state.getJSONArray("apps"),wanted=new JSONArray();int icons=0;for(String pkg:new String[]{"com.tencent.mm","com.autonavi.minimap","com.tencent.qqmusic","com.tencent.wework","com.baidu.netdisk"}){boolean found=false;for(int i=0;i<apps.length();i++)if(pkg.equals(apps.getJSONObject(i).getString("package")))found=true;wanted.put(new JSONObject().put("package",pkg).put("installed_and_selectable",found).put("already_selected",access.allowed(pkg)));}for(int i=0;i<apps.length();i++)if(apps.getJSONObject(i).optString("icon").startsWith("data:image/png;base64,"))icons++;Config c=Config.load(a);out.put("passed",true).put("discoverable_apps",apps.length()).put("icons",icons).put("categories",state.getJSONArray("categories").length()).put("requested_examples",wanted).put("existing_selected_count",access.approved().size()).put("key_present",!c.key.isEmpty()).put("wps_existing_scope",new RoutineAccess(a).allows(c,java.util.Collections.singletonList("cn.wps.moffice_eng"))).put("new_scope_grants",0).put("model_calls",0).put("actions",0);}catch(Exception e){try{out.put("passed",false).put("error",e.getClass().getSimpleName());}catch(Exception ignored){}}try(FileOutputStream f=a.openFileOutput("app-inventory-contracts.json",0)){f.write(out.toString(2).getBytes("UTF-8"));}catch(Exception ignored){}}
}
